package br.com.lealinfo.vidraceiro;
import java.math.*;import java.util.*;
/** Direct decimal adaptation of audited GlassCutPacking.Calculate, not a new packing heuristic. */
public final class CutPacking {
 static final BigDecimal MAX=new BigDecimal("1000000"),M2=new BigDecimal("1000000");
 public static final String DISCLAIMER="Simulação geométrica. Não considera kerf, margens, folgas, sentido do material, têmpera ou regras de máquina. Não é ordem de produção. Medidas do vão não são medidas de corte. Confirme com o profissional.";
 public static final class Piece{final String id,description,material;final BigDecimal w,h;final int quantity;final boolean rotation;public Piece(String id,String description,String w,String h,int quantity,String material,boolean rotation){this.id=id;this.description=description;this.w=new BigDecimal(w);this.h=new BigDecimal(h);this.quantity=quantity;this.material=material.trim();this.rotation=rotation;}}
 static final class Cell{final BigDecimal x,y,w,h;Cell(BigDecimal x,BigDecimal y,BigDecimal w,BigDecimal h){this.x=x;this.y=y;this.w=w;this.h=h;}}
 public static final class Placement{final Piece piece;final int instance;final BigDecimal x,y,w,h;final boolean rotated;Placement(Piece p,int n,Cell c,Candidate best){piece=p;instance=n;x=c.x;y=c.y;w=best.w;h=best.h;rotated=best.rotated;}}
 public static final class Sheet{final String material;final List<Cell> free=new ArrayList<>();public final List<Placement> placed=new ArrayList<>();Sheet(String m,BigDecimal w,BigDecimal h){material=m;free.add(new Cell(BigDecimal.ZERO,BigDecimal.ZERO,w,h));}}
 static final class Candidate{final int sheet,cell;final BigDecimal w,h,area,side;final boolean rotated;Candidate(int s,int f,Cell c,BigDecimal w,BigDecimal h,boolean r){sheet=s;cell=f;this.w=w;this.h=h;rotated=r;area=c.w.multiply(c.h).subtract(w.multiply(h));side=c.w.subtract(w).min(c.h.subtract(h));}}
 public static final class Result{public final BigDecimal w,h;public final List<Sheet> sheets;public final List<Piece> rejected;Result(BigDecimal w,BigDecimal h,List<Sheet> sheets,List<Piece> rejected){this.w=w;this.h=h;this.sheets=sheets;this.rejected=rejected;}public BigDecimal used(){BigDecimal n=BigDecimal.ZERO;for(Sheet s:sheets)for(Placement p:s.placed)n=n.add(p.w.multiply(p.h));return n.divide(M2);}public BigDecimal total(){return w.multiply(h).multiply(BigDecimal.valueOf(sheets.size())).divide(M2);}public BigDecimal unused(){return total().subtract(used());}public BigDecimal utilization(){return total().signum()==0?BigDecimal.ZERO:used().multiply(new BigDecimal("100")).divide(total(),8,RoundingMode.HALF_UP);}public int rejectedQuantity(){int n=0;for(Piece p:rejected)n+=p.quantity;return n;}}
 static void valid(BigDecimal v){if(v.signum()<=0||v.compareTo(MAX)>0)throw new IllegalArgumentException("Medida de corte: maior que zero e até 1.000.000 mm.");}
 static boolean fits(BigDecimal w,BigDecimal h,BigDecimal aw,BigDecimal ah){return w.compareTo(aw)<=0&&h.compareTo(ah)<=0;}
 static Candidate consider(Candidate best,int s,int f,Cell c,BigDecimal w,BigDecimal h,boolean rotate){if(!fits(w,h,c.w,c.h))return best;Candidate next=new Candidate(s,f,c,w,h,rotate);return best==null||next.area.compareTo(best.area)<0||next.area.compareTo(best.area)==0&&next.side.compareTo(best.side)<0?next:best;}
 static void add(Sheet s,BigDecimal x,BigDecimal y,BigDecimal w,BigDecimal h){if(w.signum()>0&&h.signum()>0)s.free.add(new Cell(x,y,w,h));}
 public static Result calculate(String width,String height,List<Piece> pieces,boolean rotation){BigDecimal w=new BigDecimal(width),h=new BigDecimal(height);valid(w);valid(h);if(pieces.isEmpty()||pieces.size()>1000)throw new IllegalArgumentException("Informe 1 a 1000 peças.");Set<String> ids=new HashSet<>();int count=0;for(Piece p:pieces){if(p.id.trim().isEmpty()||!ids.add(p.id.trim().toLowerCase(Locale.ROOT)))throw new IllegalArgumentException("IDs de peças devem ser únicos.");valid(p.w);valid(p.h);if(p.quantity<1||p.quantity>1000||(count+=p.quantity)>1000)throw new IllegalArgumentException("Até 1000 unidades por simulação.");}
 ArrayList<Piece> sorted=new ArrayList<>(pieces);sorted.sort((a,b)->{int area=b.w.multiply(b.h).compareTo(a.w.multiply(a.h));return area!=0?area:b.w.max(b.h).compareTo(a.w.max(a.h));});List<Sheet> sheets=new ArrayList<>();List<Piece> rejected=new ArrayList<>();for(Piece p:sorted){boolean rotate=rotation&&p.rotation;if(!fits(p.w,p.h,w,h)&&!(rotate&&fits(p.h,p.w,w,h))){rejected.add(p);continue;}for(int instance=1;instance<=p.quantity;instance++){Candidate best=null;for(int si=0;si<sheets.size();si++){Sheet s=sheets.get(si);if(!s.material.equalsIgnoreCase(p.material))continue;for(int fi=0;fi<s.free.size();fi++){Cell c=s.free.get(fi);best=consider(best,si,fi,c,p.w,p.h,false);if(rotate&&p.w.compareTo(p.h)!=0)best=consider(best,si,fi,c,p.h,p.w,true);}}if(best==null){Sheet s=new Sheet(p.material,w,h);sheets.add(s);best=consider(null,sheets.size()-1,0,s.free.get(0),p.w,p.h,false);if(rotate&&p.w.compareTo(p.h)!=0)best=consider(best,sheets.size()-1,0,s.free.get(0),p.h,p.w,true);}Sheet s=sheets.get(best.sheet);Cell cell=s.free.remove(best.cell);s.placed.add(new Placement(p,instance,cell,best));BigDecimal dw=cell.w.subtract(best.w),dh=cell.h.subtract(best.h);if(dw.compareTo(dh)>0){add(s,cell.x.add(best.w),cell.y,dw,cell.h);add(s,cell.x,cell.y.add(best.h),best.w,dh);}else{add(s,cell.x.add(best.w),cell.y,dw,best.h);add(s,cell.x,cell.y.add(best.h),cell.w,dh);}}}return new Result(w,h,sheets,rejected);}
}
